using System.Net;
using System.Net.Http.Json;
using BARANG.Core.Domain.Customers;
using BARANG.Core.Domain.Organization;
using BARANG.Core.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
using Npgsql;
using Xunit;

namespace BARANG.Core.IntegrationTests.Database;

[Collection(PostgreSqlDatabaseFixture.CollectionName)]
public sealed class CustomerFoundationTests(PostgreSqlDatabaseFixture database)
{
    [Fact]public async Task MigrationCreatesTablesPermissionsAndNoDeleteGrant(){await database.ResetAsync(TestContext.Current.CancellationToken);await using CoreDbContext db=database.CreateAdministrationCoreDbContext();string[] tables=await db.Database.SqlQueryRaw<string>("SELECT table_name AS \"Value\" FROM information_schema.tables WHERE table_schema='barang' AND table_name IN ('customers','customer_contacts','customer_addresses')").ToArrayAsync(TestContext.Current.CancellationToken);Assert.Equal(3,tables.Length);Assert.True(await db.Permissions.AnyAsync(x=>x.Code=="customer.read",TestContext.Current.CancellationToken));Assert.True(await db.Permissions.AnyAsync(x=>x.Code=="customer.manage",TestContext.Current.CancellationToken));}
    [Fact]public async Task RlsIsolatesCustomerAndChildrenAndContextDoesNotLeak(){await database.ResetAsync(TestContext.Current.CancellationToken);Guid a=Guid.NewGuid(),b=Guid.NewGuid();DateTimeOffset now=DateTimeOffset.UtcNow;Guid customerA=Guid.NewGuid(),customerB=Guid.NewGuid();await using(CoreDbContext db=database.CreateAdministrationCoreDbContext()){await db.Database.ExecuteSqlRawAsync("""
        INSERT INTO barang.lookup_types(id,company_id,code,display_name,scope,is_system,is_active,allow_custom_values,created_at_utc,updated_at_utc,version) VALUES
        ('14000000-0000-0000-0000-000000000001',NULL,'address.type','Address type','Global',TRUE,TRUE,FALSE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1),
        ('14000000-0000-0000-0000-000000000002',NULL,'contact.role','Contact role','Global',TRUE,TRUE,FALSE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1) ON CONFLICT DO NOTHING;
        INSERT INTO barang.lookup_values(id,lookup_type_id,company_id,code,display_order,is_active,is_system,created_at_utc,updated_at_utc,version) VALUES
        ('14000000-0000-0000-0000-000000000011','14000000-0000-0000-0000-000000000001',NULL,'office',10,TRUE,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1),
        ('14000000-0000-0000-0000-000000000012','14000000-0000-0000-0000-000000000002',NULL,'general',10,TRUE,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1) ON CONFLICT DO NOTHING;
        """,TestContext.Current.CancellationToken);db.Companies.Add(Company.Create(a,"CUST_A","A",now).Value);db.Companies.Add(Company.Create(b,"CUST_B","B",now).Value);Customer ca=Customer.Create(customerA,a,"A-1",CustomerType.Person,null,"Alice","Smith",null,null,null,null,"09120000001",null,null,null,now).Value;Customer cb=Customer.Create(customerB,b,"B-1",CustomerType.Organization,null,null,null,"Beta Ltd",null,null,null,null,null,null,null,now).Value;db.Customers.AddRange(ca,cb);db.IndividualCustomerProfiles.Add(IndividualCustomerProfile.Create(Guid.NewGuid(),customerA,a,firstName:"Alice",lastName:"Smith",nationalId:null,fatherName:null,birthDate:null,genderCode:null,birthCertificateNumber:null,placeOfIssue:null,occupation:null,now:now).Value);db.LegalCustomerProfiles.Add(LegalCustomerProfile.Create(Guid.NewGuid(),customerB,b,legalName:"Beta Ltd",tradeName:null,nationalId:null,registrationNumber:null,establishmentDate:null,legalEntityTypeCode:null,businessActivity:null,website:null,managingDirector:null,now:now).Value);db.CustomerContacts.Add(CustomerContact.Create(Guid.NewGuid(),customerB,b,type:"general",firstName:"Secret",lastName:null,mobile:null,phone:null,email:null,positionTitle:null,notes:null,primary:false,order:1,now:now).Value);db.CustomerAddresses.Add(CustomerAddress.Create(Guid.NewGuid(),customerB,b,type:"office",title:"HQ",country:"US",provinceCode:null,cityCode:null,district:null,line1:"Hidden",line2:null,postal:null,recipient:null,recipientPhone:null,recipientMobile:null,isDefault:false,order:1,now:now).Value);await db.SaveChangesAsync(TestContext.Current.CancellationToken);}await using NpgsqlConnection c=new(database.ConnectionString);await c.OpenAsync(TestContext.Current.CancellationToken);Assert.Equal((1L,0L,0L),await Counts(c,a));Assert.Equal((1L,1L,1L),await Counts(c,b));Assert.Equal((0L,0L,0L),await CountsWithoutCompany(c));Assert.Equal(0,await TryCrossCompanyUpdate(c,a,customerB));}
    [Fact]public async Task CustomerEndpointsRequireAuthenticationAndBoundPagination(){await database.ResetAsync(TestContext.Current.CancellationToken);await using PostgreSqlCoreApiFactory factory=new(database.ConnectionString);using HttpClient client=factory.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await client.GetAsync("/api/v1/customers",TestContext.Current.CancellationToken)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await client.PostAsJsonAsync("/api/v1/customers",new{},TestContext.Current.CancellationToken)).StatusCode);}
    private static async Task<(long,long,long)>Counts(NpgsqlConnection c,Guid company){await using NpgsqlTransaction tx=await c.BeginTransactionAsync(TestContext.Current.CancellationToken);await Set(c,tx,company);long customers=await Count(c,tx,"customers"),contacts=await Count(c,tx,"customer_contacts"),addresses=await Count(c,tx,"customer_addresses");await tx.RollbackAsync(TestContext.Current.CancellationToken);return(customers,contacts,addresses);}
    private static async Task<(long,long,long)>CountsWithoutCompany(NpgsqlConnection c){await using NpgsqlTransaction tx=await c.BeginTransactionAsync(TestContext.Current.CancellationToken);long customers=await Count(c,tx,"customers"),contacts=await Count(c,tx,"customer_contacts"),addresses=await Count(c,tx,"customer_addresses");await tx.RollbackAsync(TestContext.Current.CancellationToken);return(customers,contacts,addresses);}
    private static async Task<int>TryCrossCompanyUpdate(NpgsqlConnection c,Guid company,Guid target){await using NpgsqlTransaction tx=await c.BeginTransactionAsync(TestContext.Current.CancellationToken);await Set(c,tx,company);await using NpgsqlCommand cmd=new("UPDATE barang.customers SET display_name='leak' WHERE id=@id",c,tx);cmd.Parameters.AddWithValue("id",target);int result=await cmd.ExecuteNonQueryAsync(TestContext.Current.CancellationToken);await tx.RollbackAsync(TestContext.Current.CancellationToken);return result;}
    private static async Task Set(NpgsqlConnection c,NpgsqlTransaction tx,Guid company){await using NpgsqlCommand cmd=new("SELECT set_config('barang.company_id',@company,true)",c,tx);cmd.Parameters.AddWithValue("company",company.ToString());await cmd.ExecuteNonQueryAsync(TestContext.Current.CancellationToken);}private static async Task<long>Count(NpgsqlConnection c,NpgsqlTransaction tx,string table){await using NpgsqlCommand cmd=new($"SELECT count(*) FROM barang.{table}",c,tx);return Convert.ToInt64(await cmd.ExecuteScalarAsync(TestContext.Current.CancellationToken),System.Globalization.CultureInfo.InvariantCulture);}
}